targets.query:
from(bucket: v.defaultBucket) |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
 |> filter(fn: (r) => r._measurement == "ehg_raw" and r.node_id =~ /^${node:regex}$/ and r._field =~ /^c[0-9]+$/)
 |> aggregateWindow(every: v.windowPeriod, fn: last, createEmpty: false)

from(bucket: v.defaultBucket) |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
 |> filter(fn: (r) => r._measurement == "ehg_metric" and r.node_id =~ /^${node:regex}$/ and r._field == "frames_present")
 |> map(fn: (r) => ({r with _value: 100.0 * float(v: r._value) / 1200.0}))

from(bucket: v.defaultBucket) |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
 |> filter(fn: (r) => r._measurement == "ehg_metric" and r.node_id =~ /^${node:regex}$/ and r._field == "flatline")
 |> map(fn: (r) => ({r with _value: if r._value then 1 else 0}))
